from ta_messaging.message_dispatcher import *
from ta_messaging.message_sources.message_source_base import *
from ute_common_abstract_core.scope import current_scope
from ute_common_abstract_core.network_elem_identification import NotifyingCreator
from ute_common_abstract_core.network_elem_identification import MsgSourceIdentification


class MessageManager(object):
    '''
    Object responsible for  control message sources, message dispatcher and flow with observers.
    '''
    MessageManager_instance = None

    def __new__(cls, *args, **kwargs):
        if not cls.MessageManager_instance:
            cls.MessageManager_instance = super(MessageManager, cls).__new__(cls, *args, **kwargs)
            cls.MessageManager_instance.initialized = False
        return cls.MessageManager_instance

    def __init__(self):
        '''
        At init in future MM should get sources config from get_message_sources_configuration_from_tl().
        At current release all source are created by start_source by create_x_alias robot keywords.
        '''
        if self.initialized:
            return
        self._sources = {}  # (NE-type, tool, tool_specific_id): msg_sources of that NE&tool-identification
        self._dispatcher = MessageDispatcher(queues_list=[])
        self.logger = logging.getLogger('messaging')
        self.logger_msgs = logging.getLogger('messaging.flows.logic')
        self._show_messaging_help()
        self.logger.info("%s created" % self)
        self.initialized = True
        self._subscribe_for_msg_source_creation()

    @property
    def dispatcher(self):
        """
        Returns dispatcher reference
        :return:
        """
        return self._dispatcher

    def _show_messaging_help(self):
        if 'AL_DEBUG_LEVEL' not in os.environ:
            help_info = """
            ------------------------------------------------------------------------------------
            To have additional (internal) logs for ta_messaging you need either:
            export AL_DEBUG_LEVEL=TRACE                (configuration from bash)  or
            os.environ['AL_DEBUG_LEVEL'] = 'TRACE'     (configuration from python)

            look for logs named like:  messaging.XXXX.log
            ------------------------------------------------------------------------------------
            """
            self.logger_msgs.debug(help_info)

    def _subscribe_for_msg_source_creation(self):
        '''
        Register callback that should be called whenever new MsgSourceIdentification is created
        '''
        NotifyingCreator.notify(self.start_source)  # to pass bound method

    def __str__(self):
        total_sources_number = 0
        for ne_toolbased_id in self._sources:
            total_sources_number += len(self._sources[ne_toolbased_id])
        active_msg_sources = 'msg_src#:%d' % total_sources_number
        class_name = self.__class__.__name__
        return '%s(%s)' % (class_name, active_msg_sources)

    def register_source_for_current_scope(self, source):
        '''
        Registers new resource to current scope.

        :param source: instance of MessageSource
        '''
        current_scope().uses(source, self.stop_source)

    def start_source(self, net_elem_identification):  # need @staticmethod ?
        """
        :param net_elem_identification: id of NE
        """
        if not isinstance(net_elem_identification, MsgSourceIdentification):
            return  # we create message sources only for MsgSourceIdentification
        if net_elem_identification.specific_for_tool is None:
            return  # NEidentification must have tool_specific_id to be able to create message_source for it

        ne_type = net_elem_identification.network_elem_type
        tool_type = net_elem_identification.specific_for_tool
        ne_toolbased_id = (ne_type, tool_type, str(net_elem_identification.tool_specific_id))
        if ne_toolbased_id in self._sources:
            return  # we already have message_sources for that ne_toolbased_id

        self._sources[ne_toolbased_id] = None  # secure against recursion danger!!!
        message_sources_of_net_elem = self._handle_source_thread_start(ne_toolbased_id, net_elem_identification)
        for source in message_sources_of_net_elem:
            self._dispatcher.add_source(source.queue)
            self.register_source_for_current_scope(source)
            self.logger_msgs.info('%s created %s for %s' % (self, source, net_elem_identification))

    def _handle_source_thread_start(self, ne_toolbased_id, net_elem_identification):
        try:
            message_sources_of_net_elem = create_and_start_additional_sources(net_elem_identification)
            self._sources[ne_toolbased_id] = message_sources_of_net_elem
        except Exception as e:
            del self._sources[ne_toolbased_id]
            raise e
        return message_sources_of_net_elem

    def stop_source(self, source):
        '''
        Function called by scope register to remove source based on creation scope

        :param source: instance of MessageSource
        '''
        self.logger_msgs.info('{} is trying to remove source {} for {}'.format(self, source, current_scope()))
        for ne_toolbased_id in self._sources:
            message_sources_of_net_elem = self._sources[ne_toolbased_id]
            if source in message_sources_of_net_elem:
                self._dispatcher.remove_source(source.queue)
                source.stop()
                message_sources_of_net_elem.remove(source)
                self.logger_msgs.info('{} removed source {} for {}'.format(self, source, current_scope()))
                if len(message_sources_of_net_elem) == 0:  # last source of alias
                    del self._sources[ne_toolbased_id]
                break
        else:
            self.logger_msgs.info('{} does not have source {} for {}'.format(self, source, current_scope()))

    def _clean_sources(self):
        #  TO DO how to clean sources from message manager? Is that required?
        for ne_toolbased_id in self._sources:
            message_sources_of_net_elem = self._sources[ne_toolbased_id]
            for source in message_sources_of_net_elem:
                source.stop()
        self._sources = {}

    def stop(self):
        '''
        Performs cleaning
        '''
        self._clean_sources()
        self._dispatcher.stop()
        self.initialized = False
